import{_ as r,l,o as t,c as n,v as e,p as h,x as o,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"双光子 3D 打印","description":"","frontmatter":{"title":"双光子 3D 打印","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/two-photon-3d.md","filePath":"litho/two-photon-3d.md","lastUpdated":1789023840000}'),c={name:"litho/two-photon-3d.md"};function _(E,a,m,A,u,f){const i=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="双光子-3d-打印" tabindex="-1">双光子 3D 打印 <a class="header-anchor" href="#双光子-3d-打印" aria-label="Permalink to &quot;双光子 3D 打印&quot;">​</a></h1><div class="epigraph"><p>聚合速率跟强度平方走，反应被关在焦点体素里；可以写出真三维聚合物，吞吐却按体素串行。</p><footer>—— 对照 two-photon polymerization（Nanoscribe 一类）的公开原理</footer></div><p><a href="/litho/grayscale-litho">上一课</a>用二维剂量做高度。缺口是任意三维。本课钉双光子 3D 打印。生物芯片光刻作为另一应用域，留给[下一课](/litho/biochip-litho）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双光子聚合：近红外飞秒激光，只有焦点附近强度够发生双光子吸收，体素外几乎不聚合。可写悬空波导、超材料、微针。分辨率可到亚微米体素，但速度是扫描体素——再遇直写面积/体积墙，只是对象是体积。量产 IC 无关；微光学、生物医学、研究是尼奇。</p><p>缺口是<strong>体积串行</strong>，不是投影并行。把双光子当 High-NA 之后的量产接班，wph 算术不成立。</p><h3 id="与远场衍射" tabindex="-1">与远场衍射 <a class="header-anchor" href="#与远场衍射" aria-label="Permalink to &quot;与远场衍射&quot;">​</a></h3><p>非线性阈值可以让有效体素小于线性衍射斑，这是「超分辨」叙事的来源。仍不是 EUV 替代，材料是聚合物不是硅前道。</p><p><span class="marginnote">多焦点并行与投影式双光子在研究中，要过的仍是体积×剂量墙。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：飞秒激光、压电/扫描台、负胶体系。设计：3D CAD。后处理：显影未聚合树脂。与灰度：灰度快、形状受限；双光子慢、形状自由。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>极化率二阶过程 ∝ I²，焦点外 I 下降则反应骤降。体素尺寸由数值孔径、阈值、扫描速度决定。串行时间 ∝ 体积 / 体素 / 扫描占空比。</p>',13)),(t(),h(p,null,{default:o(()=>[d(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22%E9%A3%9E%E7%A7%92%E7%84%A6%E7%82%B9%22%5D%20--%3E%20TPP%5B%22I%C2%B2%20%E9%98%88%E5%80%BC%E4%BD%93%E7%B4%A0%22%5D%0A%20%20TPP%20--%3E%20SHAPE%5B%22%E4%BB%BB%E6%84%8F%203D%20%E8%81%9A%E5%90%88%E7%89%A9%22%5D%0A%20%20SHAPE%20--%3E%20WALL%5B%22%E4%BD%93%E7%A7%AF%E4%B8%B2%E8%A1%8C%E5%A2%99%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不服务硅前道量产。不把某商家最小特征当物理极限常数。材料收缩与机械强度是产品问题。</p><p>后课默认：真三维聚合物直写存在且慢；下一课生物芯片常用更经典的平面光刻做流道与阵列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双光子用 I² 阈值写出三维体素，形状自由、吞吐串行。</li><li>非线性可小于线性斑，仍不是 IC 量产路径。</li><li>与灰度二维高度映射互补。</li><li>出处：two-photon polymerization 公开原理。</li></ul>',5))])}const D=r(c,[["render",_]]);export{B as __pageData,D as default};
